class PRBSGenerator:
    def __init__(self, prbs_length, start_value):
        if prbs_length == 15:
            self.poly = 0xC001 >> 1
        elif prbs_length == 20:
            self.poly = 0x80005 >> 1
        elif prbs_length == 23:
            self.poly = 0x840001 >> 1
        else:
            assert prbs_length == 31
            self.poly = 0xA0000001 >> 1
        self.state = start_value
        self.prbs_length = prbs_length

    def generate(self):
        feedback_bit = self.state & 1
        self.state >>= 1
        if feedback_bit:
            self.state ^= self.poly
        return feedback_bit
