from sympy import symbols, sympify, lambdify

class SymbolicDifferentiation:
    def __init__(self, expression):
        self.vars = symbols('x y z')  # Define the symbolic variables
        self.f = sympify(expression)  # Convert the input expression to a SymPy expression
        self.lambdified_f = lambdify(self.vars, self.f)  # Create a callable function for the expression

