public class SumOfSquares {
    private static int[] sqSum = new int[1000];

    static {
        for (int i = 0; i < 1000; i++) {
            sqSum[i] = calculateSqSum(i);
        }
    }

    public static int calculate(int n) {
        int result = 0;
        while (n > 0) {
            result += sqSum[n % 1000];
            n /= 1000;
        }
        return result;
    }

    private static int calculateSqSum(int num) {
        int sum = 0;
        while (num > 0) {
            int digit = num % 10;
            sum += digit * digit;
            num /= 10;
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(calculate(123456)); // Output: 91
    }
}
