class KMeans:
    def __init__(self, k=2, tol=0.001, max_iter=300):
        self.k = k
        self.tol = tol
        self.max_iter = max_iter

    def fit(self, data):
        """Compute k-means clustering."""
        self.centroids = centroids = dict()

        for i in range(self.k):
            centroids[i] = data[i]

        for _ in range(self.max_iter):
            prev_centroids = dict(centroids)
            clusters = {i: [] for i in range(self.k)}

            # Assign each data point to the nearest centroid
            for point in data:
                distances = [((point - centroids[i]) ** 2).sum() for i in range(self.k)]
                cluster_index = distances.index(min(distances))
                clusters[cluster_index].append(point)

            # Update centroids as the mean of the assigned data points
            for i in range(self.k):
                if clusters[i]:
                    centroids[i] = sum(clusters[i]) / len(clusters[i])

            # Check for convergence
            converged = True
            for i in range(self.k):
                if (centroids[i] - prev_centroids[i]).sum() > self.tol:
                    converged = False
                    break

            if converged:
                break
