import mistune

class PopupBlockLexer(mistune.BlockLexer):
    """Support for "popups" in Markdown.

    Popups are block level elements that renders as Info/Note/Warning blocks in Confluence; the
    syntax is ~? for info popups, ~! for note and ~% for warnings.
    """

    def enable_popup_blocks(self):
        self.rules.popup_block = re.compile(r'^~[?!%]\s*(.*)')

    def parse_popup_block(self, m):
        block_type = m.group(0)[1]
        content = m.group(1)
        if block_type == '?':
            return self.renderer.popup_info_block(content)
        elif block_type == '!':
            return self.renderer.popup_note_block(content)
        elif block_type == '%':
            return self.renderer.popup_warning_block(content)

    def parse(self, text, state):
        m = self.rules.popup_block.match(text)
        if m:
            state.tokens.append(self.parse_popup_block(m))
            return True
```

