import pic

def parse_tree(s):
    stack = []
    i = 0
    while i < len(s):
        if s[i] == '(':
            stack.append('(')
        elif s[i] == 'H' or s[i] == 'V':
            stack.append(s[i])
        elif s[i] == 'L':
            color_start = s.find(' ', i)
            color_end = s.find(')', color_start)
            color = s[color_start+1:color_end]
            stack.append(('L', color))
            i = color_end
        elif s[i] == ')':
            op = stack.pop()
            colors = []
            weights = []
            while stack[-1] != '(':
                if stack[-1] == 'L':
                    colors.append(stack.pop()[1])
                else:
                    weights.append(float(stack.pop()))
            stack.pop()  # Remove the opening parenthesis
            if op == 'H':
                result_color = combine_horizontal(colors, weights)
            else:
                result_color = combine_vertical(colors, weights)
            stack.append(('L', result_color))
        i += 1
    return stack.pop()[1]

def combine_horizontal(colors, weights):
    result_color = [0, 0, 0]  # Initialize with black color
    for i in range(len(colors)):
        for j in range(3):  # RGB channels
            result_color[j] += weights[i] * colors[i][j]
    return tuple(int(val) for val in result_color)

def combine_vertical(colors, weights):
    result_color = [0, 0, 0]  # Initialize with black color
    total_weight = sum(weights)
    for i in range(len(colors)):
        for j in range(3):  # RGB channels
            result_color[j] += (weights[i] / total_weight) * colors[i][j]
    return tuple(int(val) for val in result_color)

def generate_image_from_tree(s, width, height, output_file):
    target_image = pic.pic2rgb("../data/img03.jpg", width, height)
    cf.set_target_image(target_image)
    matrix = parse_tree(s)
    pic.rgb2pic(matrix, 'LAB', output_file)

# Example usage
