class DatabaseMigrator:
    def __init__(self, schema):
        self.schema = schema
        self.migration_history = {}  # Store the migration history

    def revert_migration(self, migration_name):
        if migration_name in self.migration_history:
            changes_to_revert = self.migration_history[migration_name]
            for change in reversed(changes_to_revert):
                if change['type'] == 'drop':
