class LinkedList:
    def __init__(self):
        self.head = None

    def get_node(self, start_node, n):
        # Returns the nth node from the start_node
        # If there are fewer than n nodes, return None
        current = start_node
        for _ in range(n - 1):
            if current is not None:
                current = current.link
            else:
                return None
        return current

    def delete_every_n_nodes(self, n):
        current = self.head
        while current is not None:
            # keep the next n-1 unchanged
            previous = self.get_node(current, n - 1)
            # every time when get_node is called, we need to check if the returned result is None before proceeding to the next step
            if previous is not None:
                # delete the next n by changing the pointer of previous to the next n node
                current = self.get_node(previous.link, n)
                previous.link = current
            else:
                # if the previous is None, it means the next n-1 (at most) is unchanged, so current = None to stop the loop
                current = None
