class VersionNumber:
    def __init__(self, major, minor, patch, release_level, release_number):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.release_level = release_level
        self.release_number = release_number

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch} {self.release_level} {self.release_number}"

    def __eq__(self, other):
        return (self.major, self.minor, self.patch, self.release_level, self.release_number) == \
               (other.major, other.minor, other.patch, other.release_level, other.release_number)

    def __lt__(self, other):
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch
        if self.release_level != other.release_level:
            levels = {"alpha": 0, "beta": 1, "final": 2}
            return levels[self.release_level] < levels[other.release_level]
        return self.release_number < other.release_number

