import tensorflow as tf
from const import DECAY_TYPES

class ScheduleWithWarmup(tf.keras.optimizers.schedules.LearningRateSchedule):
    def __init__(self, base, end, total_steps, warmup_steps=10_000, decay_type="linear"):
        self.base = base
        self.end = end
        self.total_steps = total_steps
        self.warmup_steps = warmup_steps
        self.decay_type = decay_type

    def __call__(self, step):
        global_step = tf.cast(step, tf.float32)
        warmup_schedule = self.base + (self.end - self.base) * (global_step / self.warmup_steps)

        if self.decay_type == DECAY_TYPES.LINEAR:
            decay_schedule = self.end + (self.base - self.end) * (1 - (global_step - self.warmup_steps) / (self.total_steps - self.warmup_steps))
        elif self.decay_type == DECAY_TYPES.EXPONENTIAL:
            decay_schedule = self.base + (self.end - self.base) * tf.math.exp(-1.0 * (global_step - self.warmup_steps) / (self.total_steps - self.warmup_steps))
        elif self.decay_type == DECAY_TYPES.COSINE:
            cosine_decay = 0.5 * (1 + tf.math.cos(tf.constant(np.pi) * (global_step - self.warmup_steps) / (self.total_steps - self.warmup_steps)))
            decay_schedule = self.end + (self.base - self.end) * cosine_decay
        else:
            raise ValueError("Invalid decay type")

        return tf.where(global_step < self.warmup_steps, warmup_schedule, decay_schedule)
```
In the solution, the `__call__` method calculates the learning rate at each step based on the provided parameters and the chosen decay type. It first calculates the warmup schedule and then applies the specified decay type to calculate the decay schedule. The appropriate schedule is returned based on the current step. If an invalid decay type is provided, a `ValueError` is raised.

