        if item_name in self.inventory:
            self.inventory[item_name]['quantity'] += quantity
        else:
            self.inventory[item_name] = {'quantity': quantity, 'price': price}

    def insert_coin(self, coin):
        if coin in [1, 5, 10, 25]:
            self.total_money_inserted += coin
        else:
            print("Invalid coin inserted. Please use 1, 5, 10, or 25 cent coins.")

    def select_item(self, item_name):
        if item_name in self.inventory:
            item = self.inventory[item_name]
            if item['quantity'] > 0 and self.total_money_inserted >= item['price']:
                change = self.total_money_inserted - item['price']
                if change > 0:
                    self.return_change(change)
                self.total_money_inserted = 0
                self.inventory[item_name]['quantity'] -= 1
                return f"Dispensing {item_name}"
            elif item['quantity'] == 0:
                return f"{item_name} is out of stock."
            else:
                return f"Insufficient money inserted for {item_name}."
        else:
            return f"{item_name} is not available in the vending machine."

    def return_change(self, change):
        coins = [25, 10, 5, 1]
        change_coins = []
        while change > 0:
            for coin in coins:
                while change >= coin:
                    change_coins.append(coin)
                    change -= coin
        return change_coins
