class ConnectFour:
    def __init__(self, rows=6, cols=7):
        self.rows = rows
        self.cols = cols
        self.grid = [[' ' for _ in range(cols)] for _ in range(rows)]

    def display_grid(self):
        for row in self.grid:
            print('|'.join(row))
        print('-' * self.cols * 2)

    def drop_disc(self, col, player):
        for row in range(self.rows - 1, -1, -1):
            if self.grid[row][col] == ' ':
                self.grid[row][col] = str(player)
                return True
        return False

    def check_win(self, player):
        # Check horizontal
        for row in range(self.rows):
            for col in range(self.cols - 3):
                if all(self.grid[row][col + i] == str(player) for i in range(4)):
                    return True

        # Check vertical
        for col in range(self.cols):
            for row in range(self.rows - 3):
                if all(self.grid[row + i][col] == str(player) for i in range(4)):
                    return True

        # Check diagonal (top-left to bottom-right)
        for row in range(self.rows - 3):
            for col in range(self.cols - 3):
                if all(self.grid[row + i][col + i] == str(player) for i in range(4)):
                    return True

        # Check diagonal (bottom-left to top-right)
        for row in range(3, self.rows):
            for col in range(self.cols - 3):
                if all(self.grid[row - i][col + i] == str(player) for i in range(4)):
                    return True

        return False

