class Container:
    def __init__(self):
        self.children = []  # List of child containers

    def add_child(self, child):
        """Adds a child container to the current container."""
        self.children.append(child)

    def has_descendant(self, ctr):
        """(Container): bool
        Returns true if 'ctr' is a descendant of this Container.
        """
        stack = deque()
        seen = set()
        stack.append(self)  # Start with the current container

        while stack:
            current = stack.pop()
            if current == ctr:
                return True  # Found the descendant

            seen.add(current)
            for child in current.children:
