import unittest

class GameTracker:
    def __init__(self, goal_position, obstacles):
        self.player_position = (0, 0)
        self.goal_position = goal_position
        self.obstacles = obstacles

    def move_player(self, direction):
        x, y = self.player_position
        if direction == "up":
            new_position = (x, y + 1)
        elif direction == "down":
            new_position = (x, y - 1)
        elif direction == "left":
            new_position = (x - 1, y)
        elif direction == "right":
            new_position = (x + 1, y)
        if new_position not in self.obstacles:
            self.player_position = new_position

    def check_obstacle(self):
        return self.player_position in self.obstacles

    def reached_goal(self):
        return self.player_position == self.goal_position

class TestGameTracker(unittest.TestCase):
    def test_game_progress(self):
        obstacles = [(1, 0), (2, 2), (3, 1)]
        game = GameTracker((3, 3), obstacles)
        game.move_player("right")
        self.assertEqual(game.player_position, (1, 0))
        self.assertTrue(game.check_obstacle())
        game.move_player("up")
        self.assertEqual(game.player_position, (1, 0))
        self.assertTrue(game.check_obstacle())
        game.move_player("right")
