def process_properties(file_contents: str) -> Dict[str, List[str]]:
    properties = {}
    entries = file_contents.strip().split('\n\n')  # Split the file contents into individual property entries

    for entry in entries:
        lines = entry.strip().split('\n')  # Split the entry into lines
        property_type = lines[1].split(':')[-1].strip()  # Extract the property type
        keywords = [line.split('-')[-1].strip() for line in lines[3:] if line.startswith('-')]  # Extract the keywords

        if property_type in properties:
            properties[property_type].extend(keywords)  # Add keywords to existing property type
        else:
