def resolve_dependencies(dependencies):
    dependency_graph = {}
    for package, dependency in dependencies:
        dependency_graph[package] = dependency

    resolved_order = []
    visited = set()

    def dfs(package):
        if package in visited:
            raise ValueError("Circular dependency detected")
        visited.add(package)
        if package in dependency_graph:
            dfs(dependency_graph[package])
        resolved_order.append(package)

    for package in dependency_graph:
        if package not in visited:
            dfs(package)

    return resolved_order[::-1]
```

