            csv_reader = csv.reader(file)
            for row in csv_reader:
                file_name, file_class = row
                if file_class in self.classes and file_name.endswith(self.ext):
                    src_file_path = os.path.join(self.src, file_name)
                    dst_file_path = os.path.join(self.dst_folder, file_name)
                    if self.opr == 'move':
                        shutil.move(src_file_path, dst_file_path)
                    elif self.opr == 'copy':
                        shutil.copy(src_file_path, dst_file_path)
                    else:
