def is_valid_subdomain(subdomain):
    if not isinstance(subdomain, str):
        return False
    if not subdomain:
        return False
    if subdomain[0] == '-' or subdomain[-1] == '-':
        return False
    parts = subdomain.split('.')
    for part in parts:
        if not part.replace('-', '').isalnum():
            return False
    return True
