        self.account_number = account_number
        self.name = name
        self.balance = balance

class BankingSystem:
    def __init__(self):
        self.accounts = {}

    def create_account(self, name: str, initial_balance: float) -> int:
        account_number = len(self.accounts) + 1
        new_account = Account(account_number, name, initial_balance)
        self.accounts[account_number] = new_account
        return account_number

    def deposit(self, account_number: int, amount: float) -> bool:
        if account_number in self.accounts:
            self.accounts[account_number].balance += amount
            return True
        return False

    def withdraw(self, account_number: int, amount: float) -> bool:
        if account_number in self.accounts:
            if self.accounts[account_number].balance >= amount:
                self.accounts[account_number].balance -= amount
                return True
        return False

    def transfer(self, from_account: int, to_account: int, amount: float) -> bool:
        if from_account in self.accounts and to_account in self.accounts:
            if self.accounts[from_account].balance >= amount:
                self.accounts[from_account].balance -= amount
                self.accounts[to_account].balance += amount
                return True
        return False
