class Pagination:
    def __init__(self, page, request_args, old_vars):
        self.page = page
        self._request_args = request_args
        self._old_vars = old_vars

    @property
    def has_next(self):
        return bool(self.page)

    @property
    def has_prev(self):
        return bool(self.page)

    @property
    def next_page(self):
        return None if not self.has_next else self.page + 1

    @property
    def prev_page(self):
        return None if not self.has_prev else self.page - 1

    def next_url(self):
        if self.has_next:
            new_vars = dict(list(self._old_vars.items()) + [('page', self.next_page)])
            return URL(args=self._request_args, vars=new_vars)
        else:
            return None

    def prev_url(self):
        if self.has_prev:
            new_vars = dict(list(self._old_vars.items()) + [('page', self.prev_page)])
            return URL(args=self._request_args, vars=new_vars)
        else:
            return None
```

