import tensorflow as tf

class DropConnectDense(tf.keras.layers.Layer):
    def __init__(self, units, drop_connect_prob=0.5):
        super(DropConnectDense, self).__init__()
        self.units = units
        self.drop_connect_prob = drop_connect_prob

    def build(self, input_shape):
        self.kernel = self.add_weight("kernel", shape=[input_shape[-1], self.units])
        self.bias = self.add_weight("bias", shape=[self.units])

    def call(self, inputs, training=None):
        if training:
            mask = tf.random.uniform(tf.shape(self.kernel)) > self.drop_connect_prob
            masked_kernel = tf.where(mask, self.kernel, 0)
            output = tf.matmul(inputs, masked_kernel) + self.bias
        else:
            output = tf.matmul(inputs, self.kernel) + self.bias
        return output

class DropConnectConv2D(tf.keras.layers.Layer):
    def __init__(self, filters, kernel_size, drop_connect_prob=0.5):
        super(DropConnectConv2D, self).__init__()
        self.filters = filters
        self.kernel_size = kernel_size
        self.drop_connect_prob = drop_connect_prob

    def build(self, input_shape):
        self.kernel = self.add_weight("kernel", shape=[self.kernel_size[0], self.kernel_size[1], input_shape[-1], self.filters])
        self.bias = self.add_weight("bias", shape=[self.filters])

    def call(self, inputs, training=None):
        if training:
            mask = tf.random.uniform(tf.shape(self.kernel)) > self.drop_connect_prob
            masked_kernel = tf.where(mask, self.kernel, 0)
            output = tf.nn.conv2d(inputs, masked_kernel, strides=[1, 1, 1, 1], padding='SAME') + self.bias
        else:
            output = tf.nn.conv2d(inputs, self.kernel, strides=[1, 1, 1, 1], padding='SAME') + self.bias
        return output
```

This solution provides custom drop connect dense and convolutional layer classes in TensorFlow. The `DropConnectDense` and `DropConnectConv2D` classes inherit from `tf.keras.layers.Layer` and allow for specifying the drop connect probability when creating an instance of the layer. The `call` method handles the drop connect behavior during both training and inference, applying the drop connect mask to the weights based on the specified probability during training.

