graph.add_vertex('Bucharest')
graph.add_vertex('Timisoara')
graph.add_edge('Mehadia', 'Bucharest')
graph.add_edge('Mehadia', 'Timisoara')
print(graph.dfs_traversal('Mehadia'))  # Output: ['Mehadia', 'Timisoara', 'Bucharest']
