class InventoryManager:
    def __init__(self, size):
        self._size = size
        self._items_list = [Item("", 0) for _ in range(size)]

    def add_item(self, item):
        for i in range(self._size):
            if self._items_list[i]._is_empty():
                self._items_list[i] = item
                break

    def sort(self, keyword=None):
        if keyword is None:
            keyword = lambda x: x.quantity  # Default sorting criterion

        for a in range(1, len(self._items_list)):
            b = 0
            while (not self._items_list[a - b]._is_empty()
                   and self._items_list[a - b - 1]._is_empty()):
                self._sort_swap(a - b)

        self._items_list.sort(key=keyword, reverse=True)

    def _sort_swap(self, index):
        self._items_list[index], self._items_list[index - 1] = self._items_list[index - 1], self._items_list[index]
