    def __init__(self, vocab):
        self._vocab = vocab
        self._index = 0
        self._keys = list(vocab.keys())

    def __iter__(self):
        return self

    def __next__(self):
        if self._index < len(self._keys):
            word = self._keys[self._index]
            idx = self._vocab[word]
            self._index += 1
            return word, idx
        else:
            raise StopIteration

# Example usage:
