import math

def calculate_min_distance(equiv_sites, peak_site, max_min_dist):
    min_dist = None
    for site in equiv_sites:
        dist = math.sqrt((site[0] - peak_site[0])**2 + (site[1] - peak_site[1])**2 + (site[2] - peak_site[2])**2)
        if min_dist is None:
