            if query.strip().split()[0].upper() == 'SELECT':
                return self.cursor.fetchall()
            else:
                self.conn.commit()
                self.affect_rows = self.cursor.rowcount
                return self.affect_rows
        except pymysql.Error as e:
            self.msg = f"Error executing the query: {e}"
            return None

    def close(self):
        if self.cursor:
            self.cursor.close()
        if self.conn:
            self.conn.close()
