import zlib

class Uri:
    def __init__(self, scheme, host, path, query, fragment):
        self.scheme = scheme
        self.host = host
        self.path = path
        self.query = query
        self.fragment = fragment

    def get_url(self):
        url = f"{self.scheme}://{self.host}{self.path}"
        if self.query:
            url += f"?{self.query}"
        if self.fragment:
            url += f"#{self.fragment}"
        return url

    def __str__(self):
        return self.get_url()

    def __hash__(self):
        return zlib.adler32(repr(self).encode())

    def __eq__(self, other):
        if isinstance(other, Uri):
            return (self.scheme, self.host, self.path, self.query, self.fragment) == (other.scheme, other.host, other.path, other.query, other.fragment)
        return False
