import threading
import time

class Buffer:
    def __init__(self, interval, flush_fn):
        self.buffer = []
        self.interval = interval
        self.flush_fn = flush_fn
        self.auto_flush_thread = None
        self.auto_flush_flag = threading.Event()

    def append(self, data):
        self.buffer.append(data)

    def flush(self):
        self.flush_fn(self.buffer)
        self.buffer.clear()

    def auto_flush(self):
        while not self.auto_flush_flag.wait(self.interval):
            self.flush()

    def start_auto_flush(self):
        if not self.auto_flush_thread or not self.auto_flush_thread.is_alive():
            self.auto_flush_flag.clear()
            self.auto_flush_thread = threading.Thread(target=self.auto_flush)
            self.auto_flush_thread.daemon = True
            self.auto_flush_thread.start()

    def stop_auto_flush(self):
        self.auto_flush_flag.set()
        if self.auto_flush_thread and self.auto_flush_thread.is_alive():
            self.auto_flush_thread.join()
