def max_sum_of_lengths(n, data, k):
    max_sum = 0
    max_sum_indices = []
    for i in range(len(data)):
        subarray_set = set()
        current_sum = 0
        for j in range(i, len(data)):
            if data[j] not in subarray_set:
                subarray_set.add(data[j])
                current_sum += len(data[j])
                if len(subarray_set) == k:
                    if current_sum > max_sum:
                        max_sum = current_sum
                        max_sum_indices = list(range(i, j+1))
                    elif current_sum == max_sum and list(range(i, j+1)) < max_sum_indices:
                        max_sum_indices = list(range(i, j+1))
            else:
                break
    return max_sum
