class SimpleStrategy(Strategy):
    def next_move(self, grid, position):
        row, col = position
        max_reward = -1
        next_position = position

        # Check neighboring cells for the highest reward
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < grid.shape[0] and 0 <= new_col < grid.shape[1]:
                if grid[new_row, new_col] > max_reward:
                    max_reward = grid[new_row, new_col]
                    next_position = (new_row, new_col)
                elif grid[new_row, new_col] == max_reward:
                    # Prioritize moving up, down, left, right
                    if dr < 0 and new_row < next_position[0]:
                        next_position = (new_row, new_col)
                    elif dr > 0 and new_row > next_position[0]:
                        next_position = (new_row, new_col)
                    elif dc < 0 and new_col < next_position[1]:
                        next_position = (new_row, new_col)
                    elif dc > 0 and new_col > next_position[1]:
                        next_position = (new_row, new_col)

        return next_position
