    result = []
    current_node = {}
    for line in lines:
        indent_level = line.index('#') // 4
        attribute = line.strip().replace('#', '').strip()
        if attribute == 'N/A':
            attribute = attribute
        elif attribute.isdigit():
            attribute = int(attribute)
        if indent_level == 0:
            if current_node:
                result.append(current_node)
            current_node = {'name': attribute}
