def matrix_operations(matrix):
    sum_even = 0
    sum_third_column = 0
    max_second_row = float('-inf')

    for row in matrix:
        for num in row:
            if num % 2 == 0:
                sum_even += num

    for row in matrix:
        sum_third_column += row[2]

