from typing import List

def complementary_sequence(sequence: str, nucleotide_map: dict) -> List[str]:
    def generate_combinations(seq, index, current, result, nucleotide_map):
        if index == len(seq):
            result.append(current)
            return
        if seq[index] in nucleotide_map:
            for nucleotide in nucleotide_map[seq[index]]:
                generate_combinations(seq, index + 1, current + nucleotide, result, nucleotide_map)
        else:
            generate_combinations(seq, index + 1, current + seq[index], result, nucleotide_map)

    sequences = []
    generate_combinations(sequence, 0, '', sequences, nucleotide_map)
    complementary_sequences = []
    for seq in sequences:
        complementary_seq = ''.join([nucleotide_map[n] for n in seq])
        complementary_sequences.append(complementary_seq)
    return complementary_sequences
