from typing import List, Tuple

class CaravelParser:
    def __init__(self):
        self.routes = {}
        self.destinations = {}

    def parse_command(self, command: str) -> None:
        tokens = command.split()
        if tokens[0] == 'route':
            route_id = tokens[1]
            self.routes[route_id] = []
        elif tokens[0] == 'destination':
            destination_name = tokens[1]
            x_coordinate = int(tokens[2])
            y_coordinate = int(tokens[3])
            self.destinations[destination_name] = (x_coordinate, y_coordinate)
        elif tokens[0] == 'link':
            route_id = tokens[1]
            destination_name = tokens[2]
            distance = int(tokens[3])
            self.routes[route_id].append((destination_name, distance))

    def get_routes(self) -> List[str]:
        return list(self.routes.keys())

    def get_destinations(self, route_id: str) -> List[Tuple[str, int, int]]:
        destinations = self.routes.get(route_id, [])
        return [(dest, self.destinations[dest][0], self.destinations[dest][1]) for dest, _ in destinations]

    def get_distance(self, route_id: str, destination_name: str) -> int:
        destinations = self.routes.get(route_id, [])
        for dest, distance in destinations:
            if dest == destination_name:
                return distance
        return -1  # Destination not found
