class CumulativeSumIterator:
    def __init__(self, data, threshold):
        self.data = data
        self.threshold = threshold
        self.index = 0
        self.cumulative_sum = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index < len(self.data):
            self.cumulative_sum += self.data[self.index]
            self.index += 1
            if self.cumulative_sum <= self.threshold:
                return self.cumulative_sum
            else:
                raise StopIteration
        else:
            raise StopIteration

