class RandomChoiceIterator:
    def __init__(self, data: List[int]):
        self.data = data
        self.index = 0
        self.shuffled_data = data.copy()
        random.shuffle(self.shuffled_data)

    def __iter__(self):
        return self

    def __next__(self) -> int:
        if self.index >= len(self.shuffled_data):
            self.index = 0
            random.shuffle(self.shuffled_data)
        result = self.shuffled_data[self.index]
        self.index += 1
        return result

