def resolve_dependencies(packages):
    installation_order = []

    def dfs(package):
        if package not in installation_order:
            for dependency in packages[package]:
                dfs(dependency)
            installation_order.append(package)

    for package in packages:
        dfs(package)

    return installation_order[::-1]
```
