        self.shift = shift

    def encrypt(self, message):
        encrypted_message = ""
        for char in message:
            if char.isalpha():
                shift_amount = self.shift % 26  # Ensure the shift is within the range of the alphabet
                if char.islower():
                    encrypted_char = chr(((ord(char) - ord('a') + shift_amount) % 26) + ord('a'))
