import ast

def parse_setup_file(file_path):
    with open(file_path, 'r') as file:
        setup_content = file.read()

    setup_dict = {}
    setup_ast = ast.parse(setup_content)

    for node in setup_ast.body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name) and node.targets[0].id == 'url':
            setup_dict['url'] = node.value.s
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'find_packages':
            setup_dict['packages'] = [arg.s for arg in node.args[1].elts if isinstance(arg, ast.Str)]

    return setup_dict
```

