        self.CCWcount = 0
        self.prevA = None
        self.prevB = None

    def update(self, A, B):
        # Update CCW count and previous values of A and B
        if self.prevA is not None and self.prevB is not None:
            if (A - self.prevA) * (B - self.prevB) > 0:
