class Path:
    def __init__(self, components, with_drive=False):
        self.components = components
        self.with_drive = with_drive

    def join(self, new_components):
        if self.with_drive:
            joined_components = [self.components[0]] + new_components
        else:
            joined_components = self.components + new_components
        return Path(joined_components, self.with_drive)

    @property
    def all_components(self):
        return self.components

    @property
    def absolute(self):
        if self.with_drive:
            return True
        elif self.components and (self.components[0] == '/' or ':' in self.components[0]):
            return True
        else:
            return False

    @property
    def relative(self):
        return not self.absolute

