import re
import os
import requests

def make_pattern(url_regex: str, extentions: list) -> re.Pattern:
    if extentions:
        ext_regex = '({})'.format('|'.join(extentions))
    else:
        ext_regex = '()'
    return re.compile(url_regex.format(extentions=ext_regex))

def download_by_pattern(url_regex: str, filenames: list, output_dir: str, *, extentions=[], encoding='windows-1251', limit=None):
    pattern = make_pattern(url_regex, extentions)
    downloaded_count = 0

    for filename in filenames:
        if limit is not None and downloaded_count >= limit:
            break

        url = filename
        if pattern.match(url):
            response = requests.get(url)
            if response.status_code == 200:
                file_path = os.path.join(output_dir, os.path.basename(url))
                with open(file_path, 'wb') as file:
                    file.write(response.content)
                downloaded_count += 1

    return downloaded_count
```

This solution defines the `download_by_pattern` function, which uses the `make_pattern` function to create a regular expression pattern based on the URL pattern and file extensions. It then iterates through the list of filenames, checks if the URL matches the pattern, downloads the file, and saves it in the specified output directory. The function respects the download limit if provided and returns the number of files downloaded.

