import numpy as np

def make_orthonormal_vector(v, ndim):
    '''Given a vector v, returns an orthonormal vector'''
    if ndim == 1:
        return np.array([-v[0]])
    elif ndim == 2:
        return np.array([v[1], -v[0]])
    else:
        raise ValueError("Unsupported number of dimensions")

def random_circle(radius, ndim, num_points):
    '''Generates random points on a circle in the specified number of dimensions'''
    n1 = np.random.randn(ndim)
    n1 /= np.linalg.norm(n1)
    n2 = make_orthonormal_vector(n1, ndim)

    theta = np.random.uniform(0, 2*np.pi, num_points)
    points = np.repeat(n1[None, :], num_points, axis=0) * np.cos(theta)[:, None] * radius + np.repeat(n2[None, :], num_points, axis=0) * np.sin(theta)[:, None] * radius
    return points
```

