import heapq

class JobScheduler:
    def __init__(self, minimum_number_of_workers, maximum_number_of_workers):
        self.min_workers = minimum_number_of_workers
        self.max_workers = maximum_number_of_workers
        self.workers = []
        self.tasks = []
        self.completed_tasks = set()

    def add_task(self, task_id, task_duration):
        self.tasks.append((task_id, task_duration))

    def allocate_workers(self):
        self.workers = list(range(self.min_workers))
        heapq.heapify(self.workers)
        self.tasks.sort(key=lambda x: x[1])
        for task in self.tasks:
            worker = heapq.heappop(self.workers)
            print(f"Task {task[0]} allocated to worker {worker}")
            heapq.heappush(self.workers, worker)
            self.completed_tasks.add(task[0])

    def get_task_status(self, task_id):
        if task_id in self.completed_tasks:
            return "completed"
        elif any(task[0] == task_id for task in self.tasks):
            return "pending"
        else:
            return "in progress"

    def get_worker_status(self, worker_id):
        if worker_id in self.workers:
            return "idle"
        else:
            return "busy"

    def get_overall_progress(self):
        total_duration = sum(task[1] for task in self.tasks)
