class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def add(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._add(self.root, value)

    def _add(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._add(node.left, value)
        else:
            if node.right is None:
                node.right = Node(value)
            else:
                self._add(node.right, value)

    def compare_tree(self, other_tree):
        return self._compare_trees(self.root, other_tree.root)

    def _compare_trees(self, node1, node2):
        if node1 is None and node2 is None:
            return True
        if node1 is not None and node2 is not None:
            return (node1.value == node2.value and
                    self._compare_trees(node1.left, node2.left) and
                    self._compare_trees(node1.right, node2.right))
        return False
```

The `BinaryTree` class contains methods to add nodes to the tree and compare the structure and values of two binary trees. The `compare_tree` method uses a recursive helper method `_compare_trees` to traverse both trees and compare their structure and node values. If the trees are structurally identical, the method returns `True`; otherwise, it returns `False`.

