    flat = [abs(val) for row in matrix for val in row]  # Flatten the matrix and get absolute values
    max_val = max(flat)  # Find the maximum absolute value in the matrix

    if max_val == 0:
        return matrix  # Return original matrix if all values are zeros

    normalized_matrix = []
    for row in matrix:
        normalized_row = []
        for val in row:
            if val == 0:
                normalized_row.append(0)
            else:
                normalized_row.append(int(val / max_val * 100))  # Normalize each value
        normalized_matrix.append(normalized_row)

    return normalized_matrix
```

