```python
class BankingSystem:
    def __init__(self):
        self.accounts = {}

    def create_account(self, account_number: str, initial_balance: float) -> None:
        if account_number in self.accounts:
            raise ValueError("Account already exists")
        self.accounts[account_number] = initial_balance

    def deposit(self, account_number: str, amount: float) -> None:
        if account_number not in self.accounts:
            raise ValueError("Account does not exist")
        self.accounts[account_number] += amount

    def withdraw(self, account_number: str, amount: float) -> bool:
        if account_number not in self.accounts:
            raise ValueError("Account does not exist")
        if self.accounts[account_number] < amount:
            return False
        self.accounts[account_number] -= amount
        return True

    def get_balance(self, account_number: str) -> float:
        if account_number not in self.accounts:
            raise ValueError("Account does not exist")
        return self.accounts[account_number]

    def transfer(self, from_account: str, to_account: str, amount: float) -> bool:
        if from_account not in self.accounts or to_account not in self.accounts:
            raise ValueError("One or both accounts do not exist")
        if self.accounts[from_account] < amount:
            return False
        self.accounts[from_account] -= amount
        self.accounts[to_account] += amount
        return True
