from decimal import Decimal, ROUND_UP, ROUND_DOWN, ROUND_HALF_UP, ROUND_HALF_DOWN, ROUND_HALF_EVEN, ROUND_CEILING

def custom_round(decimal_num, precision, rounding_mode):
    decimal_num = Decimal(decimal_num)
    precision = Decimal(precision)

    if rounding_mode == 'ROUND_UP':
        return decimal_num.quantize(precision, rounding=ROUND_UP)
    elif rounding_mode == 'ROUND_DOWN':
        return decimal_num.quantize(precision, rounding=ROUND_DOWN)
    elif rounding_mode == 'ROUND_HALF_UP':
        return decimal_num.quantize(precision, rounding=ROUND_HALF_UP)
    elif rounding_mode == 'ROUND_HALF_DOWN':
        return decimal_num.quantize(precision, rounding=ROUND_HALF_DOWN)
    elif rounding_mode == 'ROUND_HALF_EVEN':
        return decimal_num.quantize(precision, rounding=ROUND_HALF_EVEN)
    elif rounding_mode == 'ROUND_CEILING':
        return decimal_num.quantize(precision, rounding=ROUND_CEILING)
    else:
        raise ValueError("Invalid rounding mode")

# Example usage
