import pygame

class Game:
    def __init__(self):
        self.character_position = [0, 0]  # Initial position of the character
        self.grid_size = (10, 10)  # Size of the game grid
        self.mod_bits = [
            (pygame.KMOD_ALT, 'A'),
            (pygame.KMOD_CTRL, 'C'),
            (pygame.KMOD_SHIFT, 'S')
        ]

    def handle_key_events(self, event):
        mods = pygame.key.get_mods()
        mod_str = ''.join(b[1] for b in self.mod_bits if b[0] & mods)

        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_UP:
                self.move_character('UP', mod_str)
            elif event.key == pygame.K_DOWN:
                self.move_character('DOWN', mod_str)
            elif event.key == pygame.K_LEFT:
                self.move_character('LEFT', mod_str)
            elif event.key == pygame.K_RIGHT:
                self.move_character('RIGHT', mod_str)

    def move_character(self, direction, modifiers):
        # Handle movement based on direction and modifiers
        if direction == 'UP':
            if 'C' in modifiers:  # If CTRL key is pressed
                self.character_position[1] -= 2  # Move character 2 units up
            else:
                self.character_position[1] -= 1  # Move character 1 unit up
        elif direction == 'DOWN':
            if 'C' in modifiers:
                self.character_position[1] += 2
            else:
                self.character_position[1] += 1
        elif direction == 'LEFT':
            if 'C' in modifiers:
                self.character_position[0] -= 2
            else:
                self.character_position[0] -= 1
        elif direction == 'RIGHT':
            if 'C' in modifiers:
                self.character_position[0] += 2
            else:
                self.character_position[0] += 1

        # Ensure character stays within the game grid
        self.character_position[0] = max(0, min(self.character_position[0], self.grid_size[0] - 1))
        self.character_position[1] = max(0, min(self.character_position[1], self.grid_size[1] - 1))

# Initialize pygame and create a Game instance
pygame.init()
game = Game()

# Main event loop
running = True
while running:
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False
        game.handle_key_events(event)

pygame.quit()
