import threading

class StopwordManager:
    def __init__(self):
        self.stopwords = set()
        self.useThread = False
        self.fast_pattern = True

    def addStopwords(self, words):
        if self.useThread:
            thread = threading.Thread(target=self._addStopwords, args=(words,))
            thread.start()
        else:
            self._addStopwords(words)

    def _addStopwords(self, words):
        self.stopwords.update(words)

    def removeStopwords(self, words):
        if self.useThread:
            thread = threading.Thread(target=self._removeStopwords, args=(words,))
            thread.start()
        else:
            self._removeStopwords(words)

    def _removeStopwords(self, words):
        for word in words:
            if word in self.stopwords:
                self.stopwords.remove(word)

    def isStopword(self, word):
        if self.fast_pattern:
            return word in self.stopwords
        else:
            return any(word == sw for sw in self.stopwords)
