from math import sqrt

def next_prime(max_number):
    for i in range(2, max_number):
        find = True
        for k in range(2, int(sqrt(i)) + 1):
            if i % k == 0:
                find = False
                break
        if find:
            yield i

def hesapla(sayi):
    prime_factors = []
    max_number = int(sqrt(sayi)) + 1
    prime_gen = next_prime(max_number)
    next_prime_number = next(prime_gen)

    while sayi > 1 and next_prime_number <= max_number:
        if sayi % next_prime_number == 0:
            prime_factors.append(next_prime_number)
            sayi //= next_prime_number
        else:
            next_prime_number = next(prime_gen)

    if sayi > 1:
        prime_factors.append(sayi)

    return prime_factors
