import random

class CFG:
    def __init__(self):
        self.nt_symbols = set()
        self.t_symbols = set()
        self.productions = {}

    def add_production(self, nt_symbol, production):
        if nt_symbol not in self.productions:
            self.productions[nt_symbol] = []
        self.productions[nt_symbol].append(production)
        for symbol in production:
            if symbol.isupper():
                self.nt_symbols.add(symbol)
            else:
                self.t_symbols.add(symbol)

    def generate_random_string(self, nt_symbol):
        if nt_symbol not in self.productions:
            return nt_symbol
        production = random.choice(self.productions[nt_symbol])
        result = ''
        for symbol in production:
            if symbol.isupper():
                result += self.generate_random_string(symbol)
            else:
                result += symbol
        return result

