import shutil
from zipfile import ZipFile
from tempfile import mkdtemp
from scale_mesh import scale_mesh
from wearebeautiful.bundles import validate_manifest, MAX_SCREENSHOT_SIZE

def process_mesh_files(directory, target_size):
    scaled_mesh_files = []
    manifest_valid = False
    screenshot_size_valid = True

    # Scale each mesh file to the specified size
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.obj'):
                file_path = os.path.join(root, file)
                scaled_file_path = os.path.join(root, f'scaled_{file}')
                try:
                    scale_mesh(file_path, scaled_file_path, target_size)
                    scaled_mesh_files.append(scaled_file_path)
                except Exception as e:
                    print(f"Error scaling {file}: {e}")

    # Validate the manifest file
    manifest_path = os.path.join(directory, 'manifest.json')
    if os.path.exists(manifest_path):
        try:
            manifest_valid = validate_manifest(manifest_path)
        except Exception as e:
            print(f"Error validating manifest: {e}")

    # Check screenshot file sizes
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.png') or file.endswith('.jpg'):
                file_path = os.path.join(root, file)
                if os.path.getsize(file_path) > MAX_SCREENSHOT_SIZE:
                    screenshot_size_valid = False
                    print(f"Screenshot {file} exceeds maximum size")

    # Create a zip file containing the scaled mesh files and the manifest file
    if all([manifest_valid, screenshot_size_valid]):
        temp_dir = mkdtemp()
        zip_file_path = os.path.join(directory, f'mesh_files_{datetime.datetime.now().strftime("%Y%m%d%H%M%S")}.zip')
        with ZipFile(zip_file_path, 'w') as zipf:
            for file in scaled_mesh_files:
                zipf.write(file, os.path.relpath(file, directory))
            zipf.write(manifest_path, os.path.relpath(manifest_path, directory))
        shutil.rmtree(temp_dir)

    return manifest_valid, screenshot_size_valid, zip_file_path

@click.command()
@click.option('--directory', help='Directory containing mesh files')
@click.option('--target_size', type=int, help='Target size for scaling the mesh files')
def main(directory, target_size):
    manifest_valid, screenshot_size_valid, zip_file_path = process_mesh_files(directory, target_size)
    if manifest_valid and screenshot_size_valid:
        print(f"Processing completed successfully. Zip file created at: {zip_file_path}")
    else:
        print("Processing encountered errors. Please check the output for details.")

if __name__ == '__main__':
    main()
```

