    sortedB = sorted(B)
    assigned = {b: [] for b in B}
    remaining = []
    for a in A:
        if a > sortedB[0]:
            assigned[sortedB[0]].append(a)
            sortedB.pop(0)
        else:
            remaining.append(a)
    return [assigned[b].pop() if assigned[b] else remaining.pop() for b in B]
