import re

def parse_alembic_migration_file(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            revision_match = re.search(r"revision = '(.+)'", content)
            down_revision_match = re.search(r"down_revision = '(.+)'", content)
            upgrade_match = re.search(r"def upgrade\(\):\s+op.execute\(\"(.+)\"\)", content, re.DOTALL)

            if revision_match and down_revision_match and upgrade_match:
                return {
                    'revision': revision_match.group(1),
                    'down_revision': down_revision_match.group(1),
                    'sql_command': upgrade_match.group(1)
                }
            else:
                return "Invalid Alembic migration file format"
    except FileNotFoundError:
        return "File not found"
    except Exception as e:
        return f"Error occurred: {str(e)}"

