import time

class GPIO:
    def __init__(self, io0_state=False, io1_state=False, io1_pull_down=False):
        self.io0_state = io0_state
        self.io1_state = io1_state
        self.io1_pull_down = io1_pull_down

    def configure(self, ios, output=False, input=False, pull_down=False):
        if 0 in ios:
            self.io0_output = output
            self.io0_input = input
        if 1 in ios:
            self.io1_output = output
            self.io1_input = input
            self.io1_pull_down = pull_down

    @property
    def io(self):
        return self.io0_state, self.io1_state

    @property
    def io0(self):
        return self.io0_state

    @io0.setter
    def io0(self, value):
        if self.io0_output:
            self.io0_state = value
        else:
            raise ValueError("IO0 is not configured as an output")

    @property
    def io1(self):
        if self.io1_input:
            if self.io1_pull_down:
                return self.io1_state or False
            else:
                return self.io1_state
        else:
            raise ValueError("IO1 is not configured as an input")

    @io1.setter
    def io1(self, value):
        if self.io1_output:
            self.io1_state = value
        else:
            raise ValueError("IO1 is not configured as an output")

# Simulate the GPIO behavior
def simulate_gpio(iterations):
    hub = GPIO()
    hub.configure(ios=[0], output=True, input=True)
    hub.configure(ios=[1], input=True, pull_down=True)

    for _ in range(iterations):
        hub.io0 = True
        print("IO {} {}".format(*hub.io))
        time.sleep(1)

# Run the simulation for 5 iterations
simulate_gpio(5)
