// Solution using Express.js and prom-client library for Prometheus metrics

// Install the required packages using npm:
// npm install express prom-client

// Import required modules
const express = require('express');
const promClient = require('prom-client');

// Create an instance of the web application
const app = express();

// Create a Prometheus Registry
const promRegistry = new promClient.Registry();

// Create a Prometheus counter to measure the request processing time
const requestProcessingTime = new promClient.Counter({
  name: 'request_processing_time_seconds',
  help: 'Time taken to process each request',
  registers: [promRegistry],
});

// Define the prometheus_middleware function
function prometheus_middleware(req, res, next) {
  const start = process.hrtime();

  // Intercept the response finish event to measure the time taken
  res.on('finish', () => {
    const end = process.hrtime(start);
    const elapsedTime = end[0] + end[1] / 1e9; // Convert to seconds
    requestProcessingTime.inc(elapsedTime);
  });

  next();
}

// Use the prometheus_middleware in the application
app.use(prometheus_middleware);

// Define a sample route to demonstrate the middleware's functionality
app.get('/', (req, res) => {
  res.send('Hello, Prometheus!');
});

// Expose the Prometheus metrics endpoint
app.get('/metrics', (req, res) => {
  res.set('Content-Type', promRegistry.contentType);
  res.end(promRegistry.metrics());
});

// Start the web application on port 3000
app.listen(3000, () => {
  console.log('Web application running on port 3000');
});
```

