import multiprocessing

def search_files(directory_path, file_pattern):
    matching_files = []
    for root, dirnames, filenames in os.walk(directory_path):
        for filename in fnmatch.filter(filenames, file_pattern):
            matching_files.append(os.path.join(root, filename))
    return matching_files

def generate_file_report(directory_path, file_pattern, num_processes):
    try:
        with multiprocessing.Pool(processes=num_processes) as pool:
            matching_files = pool.apply(search_files, (directory_path, file_pattern))
        report = {
            "total_files": len(matching_files),
            "matching_files": matching_files
        }
        with open('file_report.json', 'w') as report_file:
            json.dump(report, report_file, indent=2)
        return report
    except FileNotFoundError:
        return {"error": "Directory not found"}
    except PermissionError:
        return {"error": "Permission denied for directory"}
    except Exception as e:
        return {"error": str(e)}

