    if flags[0] & 1:
        try:
            # Attempt to decompress the document using lzma.decompress
            working_document = lzma.decompress(document)
            logger.info("Successfully decompressed document.")
            return working_document
        except Exception as e:
            # Return an error response if decompression fails
