class CustomData:
    def __init__(self, name_type="", components=None):
        self.name_type = name_type
        self.components = components if components is not None else []

    def serialize(self):
        serialized_bytes = self.name_type.encode('utf-8')
        serialized_bytes += len(self.components).to_bytes(4, byteorder='big', signed=False)
        for component in self.components:
            serialized_bytes += len(component).to_bytes(4, byteorder='big', signed=False)
            serialized_bytes += component.encode('utf-8')
        return serialized_bytes

    @classmethod
    def deserialize(cls, data):
        name_type = data[:4].decode('utf-8')
        num_components = int.from_bytes(data[4:8], byteorder='big')
        components = []
        current_index = 8
        for _ in range(num_components):
            component_length = int.from_bytes(data[current_index:current_index + 4], byteorder='big')
            component = data[current_index + 4:current_index + 4 + component_length].decode('utf-8')
            components.append(component)
            current_index += 4 + component_length
        return cls(name_type, components)
```

