def average_temperature_change(grid):
    total_horizontal_change = 0
    total_vertical_change = 0
    count_horizontal = 0
    count_vertical = 0

    # Calculate horizontal changes
    for row in grid:
        for i in range(len(row) - 1):
            total_horizontal_change += abs(row[i] - row[i + 1])
            count_horizontal += 1

    # Calculate vertical changes
    for i in range(len(grid) - 1):
        for j in range(len(grid[i])):
            total_vertical_change += abs(grid[i][j] - grid[i + 1][j])
            count_vertical += 1

    average_horizontal_change = round(total_horizontal_change / count_horizontal, 2)
    average_vertical_change = round(total_vertical_change / count_vertical, 2)

    return (average_horizontal_change, average_vertical_change)
