def decrypt_message(encrypted_message, key):
    def is_prime(n):
        if n < 2:
            return False
        return all(n % i != 0 for i in range(2, round(pow(n, 0.5)) + 1)) or n == 2

    def calculate_pfactor(key):
        if key < 0:
            pfactor = -1
            for i in range(2, abs(key) + 1):
                if is_prime(i) and key % i == 0:
                    pfactor *= i
        else:
            pfactor = 1
            for i in range(2, key + 1):
                if is_prime(i) and key % i == 0:
                    pfactor *= i
        return pfactor

    pfactor = calculate_pfactor(key)
    decrypted_message = ''.join(chr((ord(c) - pfactor) % 128) for c in encrypted_message)
    return decrypted_message
```

