def format_text(text: str, max_line_length: int) -> str:
    words = text.split()
    formatted_text = ""
    line_length = 0

    for word in words:
        if len(word) > max_line_length:
            formatted_text += word[:max_line_length] + "\n"
            formatted_text += format_text(word[max_line_length:], max_line_length)
            line_length = len(word) % max_line_length
        elif line_length + len(word) + 1 <= max_line_length:
            formatted_text += word + " "
            line_length += len(word) + 1
        else:
            formatted_text = formatted_text.rstrip() + "\n" + word + " "
            line_length = len(word) + 1

    return formatted_text.rstrip()
```

