        self.data_source = ''
        self.language_data = []

    def set_organization_data_source(self, organization, data_source):
        self.organization = organization
        self.data_source = data_source

    def add_language_data(self, language_data):
        self.language_data.extend(language_data)

    def get_language_names(self, language_id):
        language_names = {}
        for language in self.language_data:
            if language['id'] == language_id:
                language_names['name'] = language['name']
                language_names['name_fi'] = language['name_fi']
                language_names['name_sv'] = language['name_sv']
                language_names['name_en'] = language['name_en']
                break
        return language_names

# Example usage
manager = LanguageManager()
manager.set_organization_data_source('ABC Inc.', 'xyz_source')
manager.add_language_data([
    {'id': 'fi', 'name': 'Suomi', 'name_fi': 'Suomi', 'name_sv': 'Finska', 'name_en': 'Finnish'},
    {'id': 'en', 'name': 'English', 'name_fi': 'Englanti', 'name_sv': 'Engelska', 'name_en': 'English'}
])
print(manager.get_language_names('fi'))  # Output: {'name': 'Suomi', 'name_fi': 'Suomi', 'name_sv': 'Finska', 'name_en': 'Finnish'}
